document.querySelectorAll("#dpmo-formula-dialog,#pod-formula-dialog,#cc-formula-dialog").forEach(dlg=>{const body=dlg.querySelector("tbody");const renumber=()=>Array.from(body.rows).forEach((r,i)=>r.querySelectorAll("input").forEach((x,j)=>x.name=(j===0?"metric_threshold[":j===1?"metric_points[":"condition_color[")+i+"]"));const add=dlg.querySelector(".metric-add"),remove=dlg.querySelector(".metric-remove"),sort=dlg.querySelector(".metric-sort");if(add)add.onclick=()=>{if(body.rows.length>=40)return;const r=body.rows[body.rows.length-1].cloneNode(true);r.querySelectorAll("input").forEach((x,i)=>x.value=x.type==="color"?x.value:(i===1?0:Math.max(0,Number(x.value)-1)));body.appendChild(r);renumber()};if(remove)remove.onclick=()=>{if(body.rows.length>1)body.deleteRow(-1);renumber()};if(sort)sort.onclick=()=>{Array.from(body.rows).sort((a,b)=>Number(b.cells[0].querySelector("input").value)-Number(a.cells[0].querySelector("input").value)).forEach(r=>body.appendChild(r));renumber()};const form=dlg.querySelector("form");if(form)form.addEventListener("submit",renumber);dlg.querySelectorAll("input[type=color]").forEach(input=>input.addEventListener("input",()=>{const name=input.name.split("_")[1];const preview=dlg.querySelector(".metric-colour-preview span:nth-child("+({red:1,amber:2,green:3}[name])+")");if(preview)preview.style.background=input.value}))});
